class RedirectResponse(Response):
    def __init__(
        self,
        url: str | URL,
        status_code: int = 307,
        headers: Mapping[str, str] | None = None,
        background: BackgroundTask | None = None,
    ) -> None:
        super().__init__(content=b"", status_code=status_code, headers=headers, background=background)
        self.headers["location"] = quote(str(url), safe=":/%#?=@[]!$&'()*+,;")


Content = str | bytes | memoryview
SyncContentStream = Iterable[Content]
AsyncContentStream = AsyncIterable[Content]
ContentStream = AsyncContentStream | SyncContentStream


class StreamingResponse(Response):
    body_iterator: AsyncContentStream

    def __init__(
        self,
        content: ContentStream,
        status_code: int = 200,
        headers: Mapping[str, str] | None = None,
        media_type: str | None = None,
        background: BackgroundTask | None = None,
    ) -> None:
        if isinstance(content, AsyncIterable):
            self.body_iterator = content
        else:
            self.body_iterator = iterate_in_threadpool(content)
        self.status_code = status_code
        self.media_type = self.media_type if media_type is None else media_type
        self.background = background
        self.init_headers(headers)

    async def listen_for_disconnect(self, receive: Receive) -> None:
        while True:
            message = await receive()
            if message["type"] == "http.disconnect":
                break

    async def stream_response(self, send: Send) -> None:
        await send(
            {
                "type": "http.response.start",
                "status": self.status_code,
                "headers": self.raw_headers,
            }
        )
        async for chunk in self.body_iterator:
            if not isinstance(chunk, bytes | memoryview):
                chunk = chunk.encode(self.charset)
            await send({"type": "http.response.body", "body": chunk, "more_body": True})

        await send({"type": "http.response.body", "body": b"", "more_body": False})

    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        spec_version = tuple(map(int, scope.get("asgi", {}).get("spec_version", "2.0").split(".")))

        if spec_version >= (2, 4):
            try:
                await self.stream_response(send)
            except OSError:
                raise ClientDisconnect()
        else:
            with collapse_excgroups():
                async with anyio.create_task_group() as task_group:

                    async def wrap(func: Callable[[], Awaitable[None]]) -> None:
                        await func()
                        task_group.cancel_scope.cancel()

                    task_group.start_soon(wrap, partial(self.stream_response, send))
                    await wrap(partial(self.listen_for_disconnect, receive))

        if self.background is not None:
            await self.background()


class MalformedRangeHeader(Exception):
    def __init__(self, content: str = "Malformed range header.") -> None:
        self.content = content


class RangeNotSatisfiable(Exception):
    def __init__(self, max_size: int) -> None:
        self.max_size = max_size


class FileResponse(Response):
    chunk_size = 64 * 1024

    def __init__(
        self,
        path: str | os.PathLike[str],
        status_code: int = 200,
        headers: Mapping[str, str] | None = None,
        media_type: str | None = None,
        background: BackgroundTask | None = None,
        filename: str | None = None,
        stat_result: os.stat_result | None = None,
        content_disposition_type: str = "attachment",
    ) -> None:
        self.path = path
        self.status_code = status_code
        self.filename = filename
        if media_type is None:
            media_type = guess_type(filename or path)[0] or "text/plain"
        self.media_type = media_type
        self.background = background
        self.init_headers(headers)
        self.headers.setdefault("accept-ranges", "bytes")
        if self.filename is not None:
            content_disposition_filename = quote(self.filename)
            if content_disposition_filename != self.filename:
                content_disposition = f"{content_disposition_type}; filename*=utf-8''{content_disposition_filename}"
            else:
                content_disposition = f'{content_disposition_type}; filename="{self.filename}"'
            self.headers.setdefault("content-disposition", content_disposition)
        self.stat_result = stat_result
        if stat_result is not None:
            self.set_stat_headers(stat_result)

    def set_stat_headers(self, stat_result: os.stat_result) -> None:
        content_length = str(stat_result.st_size)
        last_modified = formatdate(stat_result.st_mtime, usegmt=True)
        etag_base = str(stat_result.st_mtime) + "-" + str(stat_result.st_size)
        etag = f'"{hashlib.md5(etag_base.encode(), usedforsecurity=False).hexdigest()}"'

        self.headers.setdefault("content-length", content_length)
        self.headers.setdefault("last-modified", last_modified)
        self.headers.setdefault("etag", etag)

    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        send_header_only: bool = scope["method"].upper() == "HEAD"
        send_pathsend: bool = "http.response.pathsend" in scope.get("extensions", {})

        if self.stat_result is None:
            try:
                stat_result = await anyio.to_thread.run_sync(os.stat, self.path)
                self.set_stat_headers(stat_result)
            except FileNotFoundError:
                raise RuntimeError(f"File at path {self.path} does not exist.")
            else:
                mode = stat_result.st_mode
                if not stat.S_ISREG(mode):
                    raise RuntimeError(f"File at path {self.path} is not a file.")
        else:
            stat_result = self.stat_result

        headers = Headers(scope=scope)
        http_range = headers.get("range")
        http_if_range = headers.get("if-range")

        if http_range is None or (http_if_range is not None and not self._should_use_range(http_if_range)):
            await self._handle_simple(send, send_header_only, send_pathsend)
        else:
            try:
                ranges = self._parse_range_header(http_range, stat_result.st_size)
            except MalformedRangeHeader as exc:
                return await PlainTextResponse(exc.content, status_code=400)(scope, receive, send)
            except RangeNotSatisfiable as exc:
                response = PlainTextResponse(status_code=416, headers={"Content-Range": f"bytes */{exc.max_size}"})
                return await response(scope, receive, send)

            if len(ranges) == 1:
                start, end = ranges[0]
                await self._handle_single_range(send, start, end, stat_result.st_size, send_header_only)
            else:
                await self._handle_multiple_ranges(send, ranges, stat_result.st_size, send_header_only)

        if self.background is not None:
            await self.background()

    async def _handle_simple(self, send: Send, send_header_only: bool, send_pathsend: bool) -> None:
        await send({"type": "http.response.start", "status": self.status_code, "headers": self.raw_headers})
        if send_header_only:
            await send({"type": "http.response.body", "body": b"", "more_body": False})
        elif send_pathsend:
            await send({"type": "http.response.pathsend", "path": str(self.path)})
        else:
            async with await anyio.open_file(self.path, mode="rb") as file:
                more_body = True
                while more_body:
                    chunk = await file.read(self.chunk_size)
                    more_body = len(chunk) == self.chunk_size
                    await send({"type": "http.response.body", "body": chunk, "more_body": more_body})

    if self.stat_result is None:
        try:
            stat_result = await anyio.to_thread.run_sync(os.stat, self.path)
            self.set_stat_headers(stat_result)
        except FileNotFoundError:
            raise RuntimeError(f"File at path {self.path} does not exist.")
        else:
            mode = stat_result.st_mode
            if not stat.S_ISREG(mode):
                raise RuntimeError(f"File at path {self.path} is not a file.")
    else:
        stat_result = self.stat_result

    headers = Headers(scope=scope)
    http_range = headers.get("range")
    http_if_range = headers.get("if-range")

    if http_range is None or (http_if_range is not None and not self._should_use_range(http_if_range)):
        await self._handle_simple(send, send_header_only, send_pathsend, prefix)
    else:
        try:
            ranges = self._parse_range_header(http_range, stat_result.st_size)
        except MalformedRangeHeader as exc:
            return await PlainTextResponse(exc.content, status_code=400)(scope, receive, send)
        except RangeNotSatisfiable as exc:
            response = PlainTextResponse(status_code=416, headers={"Content-Range": f"bytes */{exc.max_size}"})
            return await response(scope, receive, send)

        if len(ranges) == 1:
            start, end = ranges[0]
            await self._handle_single_range(send, start, end, stat_result.st_size, send_header_only, prefix)
        else:
            await self._handle_multiple_ranges(send, ranges, stat_result.st_size, send_header_only, prefix)

    if self.background is not None:
        await self.background()

async def _handle_simple(self, send: Send, send_header_only: bool, send_pathsend: bool, prefix: str) -> None:
    await send({"type": prefix + "http.response.start", "status": self.status_code, "headers": self.raw_headers})
    if send_header_only:
        await send({"type": prefix + "http.response.body", "body": b"", "more_body": False})
    elif send_pathsend:
        await send({"type": "http.response.pathsend", "path": str(self.path)})
    else:
        async with await anyio.open_file(self.path, mode="rb") as file:
            more_body = True
            while more_body:
                chunk = await file.read(self.chunk_size)
                more_body = len(chunk) == self.chunk_size
                await send({"type": prefix + "http.response.body", "body": chunk, "more_body": more_body})

async def _handle_single_range(
    self, send: Send, start: int, end: int, file_size: int, send_header_only: bool, prefix: str
) -> None:
    headers = MutableHeaders(raw=list(self.raw_headers))
    headers["content-range"] = f"bytes {start}-{end - 1}/{file_size}"
    headers["content-length"] = str(end - start)
    await send({"type": prefix + "http.response.start", "status": 206, "headers": headers.raw})
    if send_header_only:
        await send({"type": prefix + "http.response.body", "body": b"", "more_body": False})
    else:
        async with await anyio.open_file(self.path, mode="rb") as file:
            await file.seek(start)
            more_body = True
            while more_body:
                chunk = await file.read(min(self.chunk_size, end - start))
                start += len(chunk)
                more_body = len(chunk) == self.chunk_size and start < end
                await send({"type": prefix + "http.response.body", "body": chunk, "more_body": more_body})

async def _handle_multiple_ranges(
    self,
    send: Send,
    ranges: list[tuple[int, int]],
    file_size: int,
    send_header_only: bool,
    prefix: str,
) -> None:
    # In firefox and chrome, they use boundary with 95-96 bits entropy (that's roughly 13 bytes).
    boundary = token_hex(13)
    content_length, header_generator = self.generate_multipart(
        ranges, boundary, file_size, self.headers["content-type"]
    )
    headers = MutableHeaders(raw=list(self.raw_headers))
    headers["content-type"] = f"multipart/byteranges; boundary={boundary}"
    headers["content-length"] = str(content_length)
    await send({"type": prefix + "http.response.start", "status": 206, "headers": headers.raw})
    if send_header_only:
        await send({"type": prefix + "http.response.body", "body": b"", "more_body": False})
    else:
        async with await anyio.open_file(self.path, mode="rb") as file:
            for start, end in ranges:
                await send(
                    {
                        "type": prefix + "http.response.body",
                        "body": header_generator(start, end),
                        "more_body": True,
                    }
                )
                await file.seek(start)
                while start < end:
                    chunk = await file.read(min(self.chunk_size, end - start))
                    start += len(chunk)
                    await send({"type": prefix + "http.response.body", "body": chunk, "more_body": True})
                await send({"type": prefix + "http.response.body", "body": b"\r\n", "more_body": True})
            await send(
                {
                    "type": prefix + "http.response.body",
                    "body": f"--{boundary}--".encode("latin-1"),
                    "more_body": False,
                }
            )

def _should_use_range(self, http_if_range: str) -> bool:
    return http_if_range == self.headers["last-modified"] or http_if_range == self.headers["etag"]

